/// Emitted when the outbound request context needed tool-pairing surgery
/// (issue #85): orphaned tool results dropped, missing results synthesized,
/// or duplicate ids renamed. Repairs are never silent — [report] carries
/// the counts and affected ids, and [providerError] is set when the pass
/// ran in response to a provider pairing error (the self-healing retry).
final class ToolPairingRepairEvent extends AgentEvent {
  const ToolPairingRepairEvent({required this.report, this.providerError});

  /// What the repair changed (empty report = detection only).
  final ToolPairingRepairReport report;

  /// Raw provider error that triggered this pass, when it ran on the
  /// retry path; null for the pre-request repair.
  final String? providerError;
}

/// The FinalizeGate task ledger parsed from the run's final assistant
/// message (gh-1412). Emitted once per run, right before [AgentEndEvent],
/// when [AgentLoopConfig.finalizeGate] is on and the answer carries a
/// `task-ledger` fenced block. Hosts persist it as a hidden
/// `task_ledger` session record (the TaskLedger — post-mortems see WHAT
/// was self-checked, the bench summary reports near-miss proximity); the
/// trajectory snapshot builder folds persisted records back on replay.
final class TaskLedgerEvent extends AgentEvent {
  const TaskLedgerEvent(this.ledger);

  /// The checklist the run finished with.
  final TaskLedger ledger;
}

/// A tool reported a partial execution result.
final class ToolExecutionUpdateEvent extends AgentEvent {
  const ToolExecutionUpdateEvent({
    required this.toolCallId,
    required this.toolName,
    required this.args,
    required this.partialResult,
  });

  /// The [ToolCall.id] being executed.
  final String toolCallId;

  /// The tool's name.
  final String toolName;

  /// The parsed tool call arguments.
  final Map<String, dynamic> args;

  /// The partial result.
  final ToolExecutionResult partialResult;
}

/// Execution of a tool call finished (successfully or with an error result).
final class ToolExecutionEndEvent extends AgentEvent {
  const ToolExecutionEndEvent({
    required this.toolCallId,
    required this.toolName,
    required this.result,
    required this.isError,
  });

  /// The [ToolCall.id] that was executed.
  final String toolCallId;

  /// The tool's name.
  final String toolName;

  /// The final result.
  final ToolExecutionResult result;

  /// Whether the result is an error (unknown tool, executor threw, blocked,
  /// aborted, or truncated arguments).
  final bool isError;
}
