      io.writeln(
        _keyStatusView.errorLine('$error', _agent.state.model.baseUrl),
      );
      return 1;
    } finally {
      _headlessMode = false;
      _autoFoldCount = 0;
      turnSub();
      await releasePowerAssertions();
      await _cubeCacheSaveQuietly();
      await interruptSub.cancel();
      await taskSub.cancel();
      hepSub?.call();
      streamJsonSub?.call();
