        await currentConfig.getFollowUpMessages?.call() ?? const <Message>[];
    if (followUpMessages.isNotEmpty) {
      // Set as pending so the inner loop processes them.
      pendingMessages = followUpMessages;
      continue;
    }
    // Final steering drain (issue #314): a steer landing between the last
    // boundary poll and this stop-check would otherwise sit queued with no
    // run left to deliver it - the loop is still alive here, so open the
    // turn now. Cap-exhausted steering stays queued for the next run.
    pendingMessages = await pollSteering(currentConfig);
    if (pendingMessages.isNotEmpty) continue;

    break;
  }

  // The FinalizeGate (gh-1412): unattended runs parse the task ledger out
  // of the FINAL assistant message so hosts persist the hidden
  // `task_ledger` record. No ledger in the answer (or the gate off) is
  // not an error — legacy answers replay unchanged.
  if (currentConfig.finalizeGate) {
    final ledger = _finalTaskLedger(newMessages);
    if (ledger != null) await emit(TaskLedgerEvent(ledger));
  }

  await emit(AgentEndEvent(List.unmodifiable(newMessages)));
  return newMessages;
}

