/// that `lib/` (which must stay `dart:io`-free) can embed:
///
/// ```sh
/// dart run scripts/gen_prompts.dart          # rewrite the .g.dart files
/// dart run scripts/gen_prompts.dart --check  # fail if the .g.dart files are stale
/// ```
