/// Whether [line] is a bare `task-ledger` heading — `#`-prefixed, bold, or
/// bare — and not a prose mention (the token alone on its line).
bool _isLedgerHeading(String line) {
  var token = line.trim();
  if (token.startsWith('#')) {
    token = token.replaceFirst(RegExp(r'^#{1,6}\s*'), '').trim();
