/// Every ledger-shaped span in [text], in document order: fenced
/// ```task-ledger blocks and unfenced `task-ledger` headings followed by
/// ledger bullets.
List<_LedgerSpan> _ledgerSpans(String text) {
  final lines = text.split('\n');
