/// stripped, so an over-eager checklist never renders.
({TaskLedger? ledger, bool producedState, int messageIndex, AssistantMessage? stripped, Message? original})? _foldTaskLedger(List<Message> messages) {
  final messageIndex = switch (messages.lastOrNull) {
    AssistantMessage() => messages.length - 1,
    _ => -1,
  };
  if (messageIndex < 0) return null;
  final message = messages[messageIndex] as AssistantMessage;
  final producedState = messages.any(
    (m) => m is AssistantMessage && m.content.any((block) => block is ToolCall),
  );
