        ledger: ledger,
        producedState: producedState,
        messageIndex: messageIndex,
        stripped: null,
        original: null,
      );
    }
    final content = List<ContentBlock>.of(message.content);
    content[i] = block.copyWith(text: strippedText);
    return (
      ledger: ledger,
      producedState: producedState,
      messageIndex: messageIndex,
      stripped: message.copyWith(content: content),
      original: message,
